class Solution {
    public int numFactoredBinaryTrees(int[] arr) {
        Arrays.sort(arr);
        Map<Integer, Long> dp = new HashMap<>();
        long mod = 1_000_000_007L;
        long ans = 0;
        for (int i = 0; i < arr.length; i++) {
            int x = arr[i];
            long ways = 1;
            for (int j = 0; j < i; j++) {
                int a = arr[j];
                if (x % a == 0) {
                    int b = x / a;
                    if (dp.containsKey(b)) {
                        ways = (ways + dp.get(a) * dp.get(b)) % mod;
                    }
                }
            }
            dp.put(x, ways);
            ans = (ans + ways) % mod;
        }
        return (int) ans;
    }
}
