class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length, n = grid[0].length;
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        for (int[] hit : hits) {
            grid[hit[0]][hit[1]]--;
        }
        UnionFind uf = new UnionFind(m * n + 1);
        int roof = m * n;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int idx = i * n + j;
                    if (i == 0) uf.union(idx, roof);
                    if (j + 1 < n && grid[i][j + 1] == 1) uf.union(idx, i * n + j + 1);
                    if (i + 1 < m && grid[i + 1][j] == 1) uf.union(idx, (i + 1) * n + j);
                }
            }
        }
        int[] res = new int[hits.length];
        for (int k = hits.length - 1; k >= 0; k--) {
            int x = hits[k][0], y = hits[k][1];
            grid[x][y]++;
            if (grid[x][y] == 0) {
                res[k] = 0;
                continue;
            }
            int oldRoof = uf.size[uf.find(roof)];
            int idx = x * n + y;
            if (x == 0) uf.union(idx, roof);
            for (int[] d : dirs) {
                int nx = x + d[0], ny = y + d[1];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 1) {
                    uf.union(idx, nx * n + ny);
                }
            }
            int newRoof = uf.size[uf.find(roof)];
            res[k] = Math.max(0, newRoof - oldRoof - 1);
        }
        return res;
    }

    class UnionFind {
        int[] parent, size;
        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
            size[n - 1] = 0;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int x, int y) {
            int px = find(x), py = find(y);
            if (px == py) return;
            if (size[px] < size[py]) {
                parent[px] = py;
                size[py] += size[px];
            } else {
                parent[py] = px;
                size[px] += size[py];
            }
        }
    }
}
