class MKAverage {
    private int m, k;
    private Queue<Integer> queue;
    private int[] fenCnt;
    private long[] fenSum;
    private static final int MAX = 100000;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        queue = new ArrayDeque<>();
        fenCnt = new int[MAX + 1];
        fenSum = new long[MAX + 1];
    }

    public void addElement(int num) {
        if (queue.size() == m) {
            int old = queue.poll();
            update(old, -1);
        }
        queue.offer(num);
        update(num, 1);
    }

    public int calculateMKAverage() {
        if (queue.size() < m) return -1;
        long tot = querySum(MAX);
        long s1 = getSumSmallest(k);
        long s2 = tot - getSumSmallest(m - k);
        long midSum = tot - s1 - s2;
        int len = m - 2 * k;
        return (int) (midSum / len);
    }

    private void update(int x, int delta) {
        long v = (long) x * delta;
        for (int i = x; i <= MAX; i += i & -i) {
            fenCnt[i] += delta;
            fenSum[i] += v;
        }
    }

    private int queryCnt(int x) {
        if (x <= 0) return 0;
        int res = 0;
        for (int i = x; i > 0; i -= i & -i) res += fenCnt[i];
        return res;
    }

    private long querySum(int x) {
        if (x <= 0) return 0;
        long res = 0;
        for (int i = x; i > 0; i -= i & -i) res += fenSum[i];
        return res;
    }

    private long getSumSmallest(int kk) {
        if (kk <= 0) return 0;
        int left = 1, right = MAX, val = MAX;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (queryCnt(mid) >= kk) {
                val = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        int cntLess = queryCnt(val - 1);
        long sumLess = querySum(val - 1);
        return sumLess + (long) val * (kk - cntLess);
    }
}
