class Solution {
    public int largestMagicSquare(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] rowPre = new int[m][n + 1];
        int[][] colPre = new int[m + 1][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rowPre[i][j + 1] = rowPre[i][j] + grid[i][j];
                colPre[i + 1][j] = colPre[i][j] + grid[i][j];
            }
        }
        for (int k = Math.min(m, n); k >= 1; k--) {
            for (int i = 0; i + k <= m; i++) {
                for (int j = 0; j + k <= n; j++) {
                    if (isMagic(grid, rowPre, colPre, i, j, k)) return k;
                }
            }
        }
        return 1;
    }
    private boolean isMagic(int[][] grid, int[][] rowPre, int[][] colPre, int r, int c, int k) {
        int sum = rowPre[r][c + k] - rowPre[r][c];
        for (int i = r; i < r + k; i++) {
            if (rowPre[i][c + k] - rowPre[i][c] != sum) return false;
        }
        for (int j = c; j < c + k; j++) {
            if (colPre[r + k][j] - colPre[r][j] != sum) return false;
        }
        int d1 = 0, d2 = 0;
        for (int i = 0; i < k; i++) {
            d1 += grid[r + i][c + i];
            d2 += grid[r + i][c + k - 1 - i];
        }
        return d1 == sum && d2 == sum;
    }
}
