class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int n = nums.length;
        int maxState = 1;
        for (int i = 0; i < numSlots; i++) {
            maxState *= 3;
        }
        int[] p3 = new int[numSlots];
        p3[0] = 1;
        for (int i = 1; i < numSlots; i++) {
            p3[i] = p3[i - 1] * 3;
        }
        int[][] dp = new int[n + 1][maxState];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < maxState; j++) {
                dp[i][j] = Integer.MIN_VALUE / 2;
            }
        }
        dp[0][0] = 0;
        for (int i = 0; i < n; i++) {
            for (int state = 0; state < maxState; state++) {
                if (dp[i][state] < 0) {
                    continue;
                }
                for (int s = 0; s < numSlots; s++) {
                    int occ = (state / p3[s]) % 3;
                    if (occ < 2) {
                        int nstate = state + p3[s];
                        int val = nums[i] & (s + 1);
                        dp[i + 1][nstate] = Math.max(dp[i + 1][nstate], dp[i][state] + val);
                    }
                }
            }
        }
        int res = 0;
        for (int state = 0; state < maxState; state++) {
            res = Math.max(res, dp[n][state]);
        }
        return res;
    }
}
