class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = 0;
        for (int n : nums) sum += n;
        if (sum % k != 0) return false;
        int target = sum / k;
        Arrays .sort(nums);
        int start = nums.length - 1;
        if (nums[start] > target) return false;
        while (start >= 0 && nums[start] == target) {
            start--;
            k--;
        }
        return partition(new int[k], nums, start, target);
    }

 private boolean partition(int[] subsets, int[] nums, int index, int target) {
        if (index < 0) return true;
        int selected = nums[index];
        for (int i = 0; i < subsets.length; i++) {
            if (subsets[i] + selected <= target && subsets[i] != 0) {
                subsets[i] += selected;
                if (partition(subsets, nums, index - 1, target)) return true;
                subsets[i] -= selected;
            }
            if (subsets[i] == 0) break;
        }
        return false;
