    public double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        double[] medians = new double[n - k + 1];
        TreeMap<Integer, Integer> small = new TreeMap<>();
        TreeMap<Integer, Integer> large = new TreeMap<>();
        int[] sizes = new int[2];
        for (int i = 0; i < n; i++) {
            if (small.isEmpty() || nums[i] <= small.lastKey()) {
                small.put(nums[i], small.getOrDefault(nums[i], 0) + 1);
                sizes[0]++;
            } else {
                large.put(nums[i], large.getOrDefault(nums[i], 0) + 1);
                sizes[1]++;
            }
            rebalance(small, large, sizes);
            if (i >= k) {
                int num = nums[i - k];
                if (small.containsKey(num)) {
                    removeKey(small, num);
                    sizes[0]--;
                } else {
                    removeKey(large, num);
                    sizes[1]--;
                }
                rebalance(small, large, sizes);
            }
            if (i >= k - 1) {
                if (k % 2 == 1) {
                    medians[i - k + 1] = (double) small.lastKey();
                } else {
                    medians[i - k + 1] = ((long) small.lastKey() + large.firstKey()) / 2.0;
                }
            }
        }
        return medians;
