    private void rebalance(TreeMap<Integer, Integer> small, TreeMap<Integer, Integer> large, int[] sizes) {
        while (sizes[0] > sizes[1] + 1) {
            int key = small.lastKey();
            removeKey(small, key);
            sizes[0]--;
            large.put(key, large.getOrDefault(key, 0) + 1);
