class Solution {
    private int[][][][] dp;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int left = firstPlayer - 1;
        int mid = secondPlayer - firstPlayer - 1;
        int right = n - secondPlayer;
        dp = new int[29][29][29][2];
        return dfs(left, mid, right);
    }

    private int[] dfs(int left, int mid, int right) {
        if (dp[left][mid][right][0] != 0) {
            return new int[]{dp[left][mid][right][0], dp[left][mid][right][1]};
        }
        if (left == right) {
            dp[left][mid][right][0] = 1;
            dp[left][mid][right][1] = 1;
            return new int[]{1, 1};
        }
        int total = left + mid + right + 2;
        int[] types = new int[total];
        int idx = 0;
        for (int i = 0; i < left; i++) types[idx++] = 0;
        types[idx++] = 1;
        for (int i = 0; i < mid; i++) types[idx++] = 2;
        types[idx++] = 3;
        for (int i = 0; i < right; i++) types[idx++] = 4;
        java.util.List<int[]> frees = new java.util.ArrayList<>();
        int initL = 0, initM = 0, initR = 0;
        for (int i = 0; i < total / 2; i++) {
            int t1 = types[i];
            int t2 = types[total - 1 - i];
            boolean spec1 = t1 == 1 || t1 == 3;
            boolean spec2 = t2 == 1 || t2 == 3;
            if (!spec1 && !spec2) {
                frees.add(new int[]{t1, t2});
            }
        }
        if (total % 2 == 1) {
            int t = types[total / 2];
            if (t == 0) initL++;
            else if (t == 2) initM++;
            else if (t == 4) initR++;
        }
        int k = frees.size();
        int minR = Integer.MAX_VALUE;
        int maxR = 0;
        for (int mask = 0; mask < (1 << k); mask++) {
            int cl = initL, cm = initM, cr = initR;
            for (int j = 0; j < k; j++) {
                int[] p = frees.get(j);
                int t = ((mask & (1 << j)) == 0) ? p[0] : p[1];
                if (t == 0) cl++;
                else if (t == 2) cm++;
                else if (t == 4) cr++;
            }
            int[] sub = dfs(cl, cm, cr);
            minR = Math.min(minR, 1 + sub[0]);
            maxR = Math.max(maxR, 1 + sub[1]);
        }
        dp[left][mid][right][0] = minR;
        dp[left][mid][right][1] = maxR;
        return new int[]{minR, maxR};
    }
