                dfs(nei, u, depth + 1, nums, adj, coprime, last, ans);
            }
        }
        last[val].removeLast();
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}
