class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indegree = new int[n];
        boolean[] hasChild = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) {
                 if (hasChild[leftChild[i]]) return false;
                 hasChild[leftChild[i]] = true;
                 indegree[leftChild[i]]++;
             }
             if (rightChild[i] != -1) {
                 if (hasChild[rightChild[i]]) return false;
                 hasChild[rightChild[i]] = true;
                 indegree[rightChild[i]]++;
             }
        }
        int rootCount = 0;
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                rootCount++;
                root = i;
            }
        }
        if (rootCount != 1) return false;
        boolean[] visited = new boolean[n];
        return dfs(root, leftChild, rightChild, visited);
    }

    private boolean dfs(int node, int[] left, int[] right, boolean[] visited) {
        if (visited[node]) return false;
        visited[node] = true;
        if (left[node] != -1 && !dfs(left[node], left, right, visited)) return false;
        if (right[node] != -1 && !dfs(right[node], left, right, visited)) return false;
        return true;
    }
}
