        for (int i = 0; i < n; i++) {
            int l = leftChild[i];
            int r = rightChild[i];
            if (l != -1) {
                if (hasParent[l]) return false;
                hasParent[l] = true;
            }
            if (r != -1) {
                if (hasParent[r]) return false;
                hasParent[r] = true;
            }
        }
        int root = -1;
