        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        boolean[] vis = new boolean[n];
        q.offer(root);
        vis[root] = true;
        int count = 1;
        while (!q.isEmpty()) {
            int node = q.poll();
            int l = leftChild[node];
            if (l != -1) {
                if (vis[l]) return false;
                vis[l] = true;
                count++;
                q.offer(l);
            }
            int r = rightChild[node];
            if (r != -1) {
                if (vis[r]) return false;
                vis[r] = true;
                count++;
                q.offer(r);
            }
        }
        return count == n;
